export interface ScreenTimes {
  dispatchTime: number;
  lastInteractiveCall?: number;
}

const screenData: Record<string, ScreenTimes> = {};

export function setScreenDispatchTime(screenId: string, dispatchTime: number) {
  screenData[screenId] = {
    ...screenData[screenId],
    dispatchTime,
  };
}

export function setScreenInteractiveTime(screenId: string, interactiveTime: number) {
  if (screenData[screenId]) {
    screenData[screenId] = {
      ...screenData[screenId],
      lastInteractiveCall: interactiveTime,
    };
  }
}

export function getScreenTimesFor(screenId: string): ScreenTimes | undefined {
  return screenData[screenId];
}
